import{_ as a,a8 as d,o,c as g,ah as s,av as h,aw as l,K as r}from"./chunks/framework.CgKDWdj8.js";import"./chunks/theme.CCmhGRzB.js";const f=JSON.parse('{"title":"AI Agent 概述","description":"","frontmatter":{"title":"AI Agent 概述","abstract":"AI Agent（智能体）核心概念概述，涵盖 Agent 的定义、与大模型的关系、感知-规划-行动工作循环及其在自动化任务中的应用范式。","created":"2026-07-09T00:00:00.000Z","tags":["AI","Agent"],"type":"概念解释","related":["[[AI 应用核心范式-MOC]]"],"reference":"","category":["🧩 AI框架与Agent","AI 应用核心范式"]},"headers":[],"relativePath":"vault/Knowledge/AI/AI Agent 概述.md","filePath":"vault/Knowledge/AI/AI Agent 概述.md","lastUpdated":1790655645000}'),i={name:"vault/Knowledge/AI/AI Agent 概述.md"};function A(b,t,c,I,p,m){const e=d("NolebaseGitContributors"),n=d("NolebaseGitChangelog");return o(),g("div",null,[t[0]||(t[0]=s('<h1 id="ai-agent-概述" tabindex="-1">AI Agent 概述 <a class="header-anchor" href="#ai-agent-概述" aria-label="Permalink to “AI Agent 概述”">​</a></h1><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to “定义”">​</a></h2><p><strong>AI Agent（人工智能代理）</strong>：一种能够感知环境、进行决策和执行动作的智能实体。不同于传统 AI，AI Agent 具备通过独立思考、调用工具去逐步完成给定目标的能力。可以是物理实体（机器人）或虚拟实体（软件程序）。</p><p>当前讨论的 AI Agent 本质是一个<strong>控制 LLM 来解决问题的代理系统</strong>。</p><h2 id="核心组成" tabindex="-1">核心组成 <a class="header-anchor" href="#核心组成" aria-label="Permalink to “核心组成”">​</a></h2><p><code>AI Agent = LLM + 记忆 + 任务规划 + 工具使用</code></p><table tabindex="0"><thead><tr><th>组件</th><th>说明</th></tr></thead><tbody><tr><td><strong>LLM</strong></td><td>任务规划和知识推理的核心引擎</td></tr><tr><td><strong>记忆（Memory）</strong></td><td>当前输入、上下文、外部知识库、网页信息等</td></tr><tr><td><strong>规划（Planning）</strong></td><td>任务分解、目标设定、路径规划</td></tr><tr><td><strong>工具（Tools）</strong></td><td>计算器、代码解释器、搜索、API 等外部能力</td></tr><tr><td><strong>行动（Action）</strong></td><td>执行具体操作并返回结果</td></tr></tbody></table><p><img src="'+h+'"></p><h2 id="工作流程" tabindex="-1">工作流程 <a class="header-anchor" href="#工作流程" aria-label="Permalink to “工作流程”">​</a></h2><ol><li><strong>Prompt 提示词</strong>：Agent 接收任务描述（含角色、背景）</li><li><strong>LLM 大模型</strong>：深入分析提示词，生成解决方案</li><li><strong>Memory 记忆</strong>：查询匹配知识库中的相关信息</li><li><strong>Planning 规划</strong>：拆解任务、制定执行计划</li><li><strong>Action 行动</strong>：调用工具执行，返回结果</li></ol><p><img src="'+l+'"></p><h2 id="主要类别" tabindex="-1">主要类别 <a class="header-anchor" href="#主要类别" aria-label="Permalink to “主要类别”">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>说明</th><th>举例</th></tr></thead><tbody><tr><td><strong>反应型 Agent</strong></td><td>根据当前环境状态直接反应</td><td>温度调节器，根据温度调整加热/制冷</td></tr><tr><td><strong>目标导向型 Agent</strong></td><td>按预设目标规划并执行序列动作</td><td>自动驾驶汽车（特斯拉）</td></tr><tr><td><strong>学习型 Agent</strong></td><td>基于历史经验不断优化表现</td><td>基于用户反馈优化的聊天机器人</td></tr></tbody></table><h2 id="五种呈现形式对比" tabindex="-1">五种呈现形式对比 <a class="header-anchor" href="#五种呈现形式对比" aria-label="Permalink to “五种呈现形式对比”">​</a></h2><table tabindex="0"><thead><tr><th>Agent 形式</th><th>Prompt</th><th>LLM</th><th>Memory</th><th>Planning</th><th>Action</th></tr></thead><tbody><tr><td><strong>Copilot 场景助理</strong></td><td>内容</td><td>大厂自研</td><td>文本+代码</td><td>无</td><td>无</td></tr><tr><td><strong>ChatGPT 对话式</strong></td><td>内容</td><td>引入/自研</td><td>文本+代码+网页</td><td>无</td><td>自带+插件</td></tr><tr><td><strong>Flow 工作流</strong></td><td>内容</td><td>引入/自研</td><td>文本+代码+网页</td><td>无</td><td>自带+插件</td></tr><tr><td><strong>Agent 自主智能体</strong></td><td>内容</td><td>引入/自研</td><td>文本+代码+网页</td><td>有</td><td>自带+插件+API+RPA</td></tr></tbody></table><h2 id="ai-agent-与传统软件的区别" tabindex="-1">AI Agent 与传统软件的区别 <a class="header-anchor" href="#ai-agent-与传统软件的区别" aria-label="Permalink to “AI Agent 与传统软件的区别”">​</a></h2><blockquote><p>AI Agent 将使软件架构的范式从面向过程迁移到面向目标。</p></blockquote><table tabindex="0"><thead><tr><th>对比项</th><th>传统软件</th><th>AI Agent</th></tr></thead><tbody><tr><td><strong>核心要素</strong></td><td>软件工程师</td><td>Agent</td></tr><tr><td><strong>机制</strong></td><td>预定义指令、逻辑、规则和启发式算法，用户按步骤操作</td><td>LLM 为基础设施，Agent 为核心，目标导向的智能体自主生成</td></tr><tr><td><strong>生产方式</strong></td><td>人类为中心，AI 辅助</td><td>AI 为中心，人类辅助</td></tr><tr><td><strong>架构</strong></td><td>解决有限范围任务</td><td>解决无限域任务</td></tr></tbody></table><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to “应用场景”">​</a></h2><table tabindex="0"><thead><tr><th>领域</th><th>应用方式</th></tr></thead><tbody><tr><td><strong>购物</strong></td><td>语音助手集成到智能音箱和手机应用，通过语音命令购物</td></tr><tr><td><strong>教育</strong></td><td>远程教育平台，提供在线学习资源和辅导</td></tr><tr><td><strong>旅游</strong></td><td>AR/VR 技术提供沉浸式旅游体验</td></tr><tr><td><strong>制造</strong></td><td>工业机器人控制，提高生产自动化水平</td></tr><tr><td><strong>金融</strong></td><td>精准风险评估和欺诈检测，增强风控能力</td></tr><tr><td><strong>医疗</strong></td><td>辅助医生分析医疗影像，提高诊断准确性和效率</td></tr></tbody></table><h2 id="实现工具" tabindex="-1">实现工具 <a class="header-anchor" href="#实现工具" aria-label="Permalink to “实现工具”">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>简介</th></tr></thead><tbody><tr><td><strong>百度 AgentBuilder</strong></td><td>智能体开发工具，提供构建、训练和部署 AI Agent 的全流程支持</td></tr><tr><td><strong>字节扣子平台</strong></td><td>快速搭建基于大模型的问答 Bot，可发布到社交平台</td></tr><tr><td><strong>昆仑万维天工 SkyAgents</strong></td><td>企业级 AI Agent 开发平台，集成大模型、知识库等模块</td></tr><tr><td><strong>AgentGPT</strong></td><td>基于 GPT-4 的开源自动化机器人，浏览器中配置和部署</td></tr><tr><td><strong>LangChain</strong></td><td>开源框架，Agents 模块支持 Agent 管理、记忆、工具集成</td></tr><tr><td><strong>AutoGen</strong></td><td>多 Agent 系统框架，多个代理对话协作解决任务</td></tr><tr><td><strong>ChatDev</strong></td><td>基于 LLM 的软件开发框架，多智能体协作实现开发全流程自动化</td></tr><tr><td><strong>CrewAI</strong></td><td>基于 LangChain 的多 Agent 协作框架，支持角色设定和任务编排</td></tr><tr><td><em>（内容由AI生成，仅供参考）</em></td><td></td></tr></tbody></table>',22)),r(e),r(n)])}const x=a(i,[["render",A]]);export{f as __pageData,x as default};
